  struct Node *cur = root;
  while (cur) {
    struct Node dummy;
    dummy.next = NULL;
    struct Node *tail = &dummy;
    struct Node *node = cur;
    while (node) {
      if (node->left) {
        tail->next = node->left;
        tail = tail->next;
      }
      if (node->right) {
        tail->next = node->right;
        tail = tail->next;
      }
      node = node->next;
    }
    cur = dummy.next;
  }
  return root;
}

