func connect(root *Node) *Node {
	cur := root
	for cur != nil {
		dummy := &Node{}
		tail := dummy
		for node := cur; node != nil; node = node.Next {
			if node.Left != nil {
				tail.Next = node.Left
				tail = tail.Next
			}
			if node.Right != nil {
				tail.Next = node.Right
				tail = tail.Next
			}
		}
		cur = dummy.Next
	}
	return root
}

class Node {
  public int val;
  public Node left;
  public Node right;
  public Node next;

  public Node() {
  }

  public Node(int _val) {
    val = _val;
  }

  public Node(int _val, Node _left, Node _right, Node _next) {
    val = _val;
    left = _left;
    right = _right;
    next = _next;
  }
}

class Solution {
  public Node connect(Node root) {
    Node cur = root;
    while (cur != null) {
      Node dummy = new Node(0);
      Node tail = dummy;
      for (Node node = cur; node != null; node = node.next) {
        if (node.left != null) {
          tail.next = node.left;
          tail = tail.next;
        }
        if (node.right != null) {
          tail.next = node.right;
          tail = tail.next;
        }
      }
      cur = dummy.next;
    }
    return root;
  }
}

class Solution:
    def connect(self, root: "Node") -> "Node":
        cur = root
        while cur:
            dummy = Node(0)
            tail = dummy
            node = cur
            while node:
                if node.left:
                    tail.next = node.left
                    tail = tail.next
                if node.right:
                    tail.next = node.right
                    tail = tail.next
                node = node.next
            cur = dummy.next
        return root

impl Solution {
  unsafe fn connect_ptr(root: *mut Node) {
    let mut cur = root;
    while !cur.is_null() {
      let mut dummy = Node::new(0);
      let mut tail: *mut Node = &mut dummy;
      let mut node = cur;
      while !node.is_null() {
        if (*node).left.is_some() {
          let left = (*node).left.as_mut().unwrap().as_mut() as *mut Node;
          (*tail).next = left;
          tail = left;
        }
        if (*node).right.is_some() {
          let right = (*node).right.as_mut().unwrap().as_mut() as *mut Node;
          (*tail).next = right;
          tail = right;
        }
        node = (*node).next;
      }
      cur = dummy.next;
    }
  }

  pub fn connect(root: Option<Box<Node>>) -> Option<Box<Node>> {
    let mut root = root;
    if let Some(r) = root.as_mut() {
      unsafe {
        Solution::connect_ptr(r.as_mut() as *mut Node);
      }
    }
    root
  }
}

const connect = (root: Node | null): Node | null => {
  let cur = root;
  while (cur) {
    const dummy = new Node(0);
    let tail: Node = dummy;
    for (let node: Node | null = cur; node; node = node.next) {
      if (node.left) {
        tail.next = node.left;
        tail = tail.next;
      }
      if (node.right) {
        tail.next = node.right;
        tail = tail.next;
      }
    }
    cur = dummy.next;
  }
  return root;
};
